const now = new Date();
const weekEnd = now.toISOString().slice(0, 10);
const weekStartDate = new Date(now);
weekStartDate.setDate(now.getDate() - 7);
const weekStart = weekStartDate.toISOString();

return [{ json: { weekStartISO: weekStart, weekStartDate: weekStart.slice(0,10), weekEndDate: weekEnd } }];

const items = $input.all().map(i => i.json);
const range = $('تحديد نطاق الأسبوع').first().json;

if (items.length === 0) {
  return [{ json: {
    week_start: range.weekStartDate,
    week_end: range.weekEndDate,
    total_complaints: 0,
    top_category: null,
    top_category_count: 0,
    top_neighborhood: null,
    top_neighborhood_count: 0,
    high_urgency_count: 0,
    summary_text: 'لا توجد شكاوى جديدة هذا الأسبوع.'
  }}];
}

function topEntry(counts) {
  const entries = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  return entries.length ? { key: entries[0][0], count: entries[0][1] } : { key: null, count: 0 };
}

const byCategory = {};
const byNeighborhood = {};
let highUrgency = 0;

for (const c of items) {
  byCategory[c.category] = (byCategory[c.category] || 0) + 1;
  byNeighborhood[c.neighborhood] = (byNeighborhood[c.neighborhood] || 0) + 1;
  if (c.urgency === 'عالي') highUrgency++;
}

const topCat = topEntry(byCategory);
const topNeigh = topEntry(byNeighborhood);

const summary = `هذا الأسبوع وصلت ${items.length} شكوى/طلب. أكثر نوع تكراراً: ${topCat.key} (${topCat.count} حالة). أكثر منطقة تأثراً: ${topNeigh.key} (${topNeigh.count} حالة). عدد الحالات العاجلة: ${highUrgency}.`;

return [{ json: {
  week_start: range.weekStartDate,
  week_end: range.weekEndDate,
  total_complaints: items.length,
  top_category: topCat.key,
  top_category_count: topCat.count,
  top_neighborhood: topNeigh.key,
  top_neighborhood_count: topNeigh.count,
  high_urgency_count: highUrgency,
  summary_text: summary
}}];
